from common import U,Q,S,T
UNITS=[
U("A101","Kalimat tindakan dan Simple Present","Menceritakan kebiasaan dengan subjek dan bentuk kata kerja yang sesuai.",
"Subjek dan predikat|V1|He she it + s/es|Akhiran y|Be versus action|Objek opsional",
"Simple Present dapat menyatakan kebiasaan dan fakta yang relatif stabil. I/you/we/they memakai bentuk dasar: We read. He/she/it atau satu nama biasanya mendapat s/es: Rafi reads; Ana watches. Konsonan + y berubah menjadi ies: study → studies, tetapi play → plays.||Temukan kata kerja inti sebelum menyusun kalimat. She is happy memakai be untuk keadaan. She studies English memakai kata kerja tindakan. Jangan menambahkan is sebelum studies. Be tidak wajib ditambahkan pada semua kalimat Inggris. Beberapa kata kerja tidak memerlukan objek: The baby sleeps.",
[("I/you/we/they + V1","They read after dinner.","Kebiasaan beberapa orang."),("He/she/it + V-s/es","Rafi studies English.","Kebiasaan satu orang.")],
("She is studies every day.","She studies every day.","Studies sudah berfungsi sebagai kata kerja; is tidak ditambahkan."),
"Rafi lives near a library. He walks there on Saturdays. His friends read comics, but Rafi studies science. The librarian helps them. They go home at four.",
"live=tinggal|walk=berjalan|study=belajar|librarian=pustakawan|after=sesudah|every=setiap",
[Q("Ana ___ English every day.","studies","study||is studies","Konsonan + y menjadi ies untuk subjek tunggal."),
Q("They ___ football on Sundays.","play","plays||are play","They memakai bentuk dasar."),
Q("He ___ cartoons after school.","watches","watchs||watch","Watch mendapat es."),
Q("Pilih kalimat yang lengkap dan benar.","The baby sleeps.","The baby is sleeps.||The baby sleep.","Subjek tunggal memakai sleeps; objek tidak wajib."),
Q("Apa yang Rafi pelajari?","science","comics||football","Bacaan membedakan kegiatan Rafi dan teman-temannya.","reading"),
S("Ubah dengan subjek She: I go to school.","She goes to school.","Go menjadi goes untuk she.")],
[T("speaking","Ceritakan dua kebiasaanmu dan dua kebiasaan tokoh lain. Pakai kata kerja berbeda.","I read at night. I walk to school. Ana studies at home. She watches cartoons on Sunday.","Empat kebiasaan|He/she mendapat s/es|Tidak menambah be sebelum V1"),
T("writing","Tuliskan profil rutinitas Rafi dalam lima kalimat memakai read, study, go, play, dan sleep.","Rafi reads after school. He studies at home. He goes to the library on Saturday. He plays football with Ana. He sleeps at nine.","Lima kata kerja terpakai|Agreement konsisten|Informasi berhubungan")],"present",("F08",)),
U("A102","Do dan does sebagai pembantu","Membuat kalimat negatif dan pertanyaan tentang kebiasaan.",
"Don't doesn't|Do does|Kembali ke V1|Wh-questions|Jawaban singkat|Subject questions",
"Untuk kata kerja biasa pada Simple Present, do/does membantu membentuk negatif dan pertanyaan. Pada he/she/it, tanda orang ketiga berpindah ke does sehingga kata kerja utama kembali ke bentuk dasar: She doesn't study; Does she study?||Kata tanya diletakkan sebelum do/does: Where does Ana live? Bandingkan dengan be: Is she ready? tidak memakai does. Pertanyaan yang menanyakan pelaku dapat memakai pola berbeda: Who lives here? Materi ini melatih pola do/does dahulu, sambil mengenalkan batas rumusnya.",
[("S + do/does + not + V1","She does not drink tea.","Negatif kebiasaan."),("Do/Does + S + V1?","Does Rafi read comics?","Pertanyaan ya/tidak."),("Wh + do/does + S + V1?","Where do they live?","Pertanyaan informasi.")],
("Does she likes tea?","Does she like tea?","Does sudah membawa penanda orang ketiga; like tetap dasar."),
"Ana likes milk, but she doesn't drink coffee. Her brother drinks tea. Do they eat breakfast together? Yes, they do. What does Ana eat? She eats bread and fruit.",
"breakfast=sarapan|together=bersama|drink=minum|coffee=kopi|bread=roti|fruit=buah",
[Q("She ___ drink coffee.","doesn't","don't||isn't","Kata kerja drink membutuhkan doesn't untuk she."),
Q("Does he ___ here?","work","works||working","Sesudah does gunakan V1."),
Q("___ do you live? — In Bandung.","Where","Who||How many","Where meminta lokasi."),
Q("Pertanyaan untuk 'She is tired' …","Is she tired?","Does she tired?||Does she is tired?","Be membentuk pertanyaan tanpa do."),
Q("Apakah Ana dan saudaranya sarapan bersama?","Yes, they do.","Yes, she does.||No, they don't.","They dalam pertanyaan merujuk dua orang.","reading"),
S("Perbaiki: He don't play tennis.","He doesn't play tennis.||He does not play tennis.","He membutuhkan doesn't + bentuk dasar.")],
[T("speaking","Wawancarai tokoh rekaan tentang tiga kebiasaan dan berikan jawaban pendek.","Do you read? Yes, I do. Does your sister read? Yes, she does. Do you drink coffee? No, I don't.","Tiga pertanyaan|Do/does tepat|Jawaban memakai pembantu yang sesuai"),
T("writing","Bandingkan kebiasaan dua tokoh dengan dua kalimat positif dan dua negatif.","Ana reads books. Rafi plays tennis. Ana doesn't play tennis. Rafi doesn't read comics.","Dua positif dua negatif|V1 setelah doesn't|Subjek rujukan jelas")],"auxiliary",("A101",)),
U("A103","Seberapa sering dan kapan","Menempatkan keterangan frekuensi dan waktu dengan benar.",
"Always usually often|Sometimes never|Adverb sebelum verb|Adverb sesudah be|At on in|Urutan informasi",
"Adverb frekuensi umumnya berada sebelum kata kerja utama: I usually walk. Dengan be, posisinya sesudah be: She is always early. Never sudah menyatakan frekuensi nol, sehingga tidak perlu not dalam kalimat standar seperti I never smoke.||Every day, twice a week, dan on Fridays memberi rincian jadwal. Jangan menyamakan usually dengan always: biasanya masih memungkinkan pengecualian. Keterangan waktu dapat di awal atau akhir kalimat. Gunakan koma setelah frasa pembuka yang panjang agar pembaca mudah mengikuti.",
[("S + usually + V","They usually eat at home.","Biasanya, dengan kemungkinan pengecualian."),("S + be + always + sifat","Ana is always early.","Frekuensi dengan be."),("twice + a + periode","twice a week","Dua kali seminggu.")],
("She always late.","She is always late.","Kalimat ini membutuhkan be; posisi netral adverb frekuensi adalah sesudah be."),
"On school days, Bima usually walks to school. On rainy days, he takes the bus. He visits the library twice a week. He is never late for library club.",
"usually=biasanya|rarely=jarang|never=tidak pernah|twice=dua kali|rainy=hujan|early=lebih awal",
[Q("Pilih urutan yang paling netral.","She usually reads at night.","She reads usually at night.||Usually she at night reads.","Adverb berada sebelum kata kerja utama."),
Q("Pilih urutan yang tepat dengan be.","He is often tired.","He often is tired always.||He does often tired.","Often biasanya sesudah be."),
Q("Twice a week berarti …","dua kali seminggu","setiap dua minggu||dua minggu sekali setahun","Twice menyatakan dua kali.","vocabulary"),
Q("I never drink coffee berarti …","Saya tidak pernah minum kopi.","Saya selalu minum kopi.||Saya kadang minum kopi.","Never sudah bermakna negatif.","meaning"),
Q("Kapan Bima naik bus?","On rainy days.","Every school day.||Only on Sundays.","Biasanya berjalan, tetapi bus saat hujan.","reading"),
S("Lengkapi dengan preposisi: ___ Fridays, we read together.","On","On dipakai sebelum nama hari.")],
[T("speaking","Jelaskan kebiasaan dengan always, usually, sometimes, dan never. Gunakan contoh rekaan bila perlu.","I always brush my teeth. I usually read at night. I sometimes draw. I never drink coffee.","Empat frekuensi berbeda|Makna konsisten|Posisi adverb tepat"),
T("writing","Buat jadwal mingguan dengan tiga kebiasaan dan satu pengecualian.","I study on Mondays. I visit the library twice a week. I usually walk to school. On rainy days, I take the bus.","Ada frekuensi dan waktu|Pengecualian jelas|At/on/in sesuai")],"frequency",("A102",)),
U("A104","Sekarang atau kebiasaan","Membedakan Present Continuous dan Simple Present melalui konteks.",
"Be + V-ing|Sedang berlangsung|Kegiatan sementara|Spelling ing|Stative verbs dasar|Kontras konteks",
"Present Continuous memakai am/is/are + V-ing untuk kegiatan yang sedang berlangsung atau situasi sementara. She is reading now berbeda dari She reads every evening. Kata now membantu, tetapi pemilihan bentuk ditentukan makna konteks, bukan hanya kata penanda.||Untuk membuat negatif, tambahkan not setelah be; untuk pertanyaan, pindahkan be ke depan subjek. Write menjadi writing; run menjadi running. Kata seperti know dan want biasanya tidak memakai continuous dalam makna keadaan yang dipelajari di sini: I know the answer.",
[("S + be + V-ing","Rafi is drawing now.","Kegiatan sedang berlangsung."),("Be + S + V-ing?","Are they studying?","Pertanyaan tentang kegiatan."),("habit ↔ now","She cooks daily; she is reading now.","Dua sudut waktu berbeda.")],
("She reading now.","She is reading now.","V-ing memerlukan be untuk Present Continuous."),
"Ana usually studies at home. Today she is working in the library because her house is noisy. Rafi is sitting beside her. They know the answer, but they are checking their notes.",
"now=sekarang|today=hari ini|beside=di sebelah|noisy=berisik|check=memeriksa|note=catatan",
[Q("Look! The cat ___ under the chair.","is sleeping","sleeps yesterday||sleep","Look mengarahkan pada kejadian berlangsung."),
Q("Every day, she ___ at seven.","wakes up","is wake up||waking up","Kebiasaan memakai Simple Present."),
Q("Bentuk -ing dari write …","writing","writeing||writting","E akhir dilepas sebelum ing."),
Q("Pilih kalimat keadaan yang lazim.","I know the answer.","I am knowing the answer.||I knowing the answer.","Know biasanya stative dalam makna ini."),
Q("Mengapa Ana belajar di perpustakaan hari ini?","Her house is noisy.","She always lives there.||Rafi has no notes.","Kegiatan hari ini merupakan situasi sementara.","reading"),
S("Ubah ke pertanyaan: They are reading.","Are they reading?","Pindahkan are sebelum they.")],
[T("speaking","Bandingkan tiga kebiasaan dengan kegiatan yang sedang dilakukan tokoh saat ini.","Ana usually reads at home, but she is reading in the library now. Rafi usually plays tennis, but he is drawing now. They usually eat rice, but they are eating bread today.","Kontras habit/now|Be tidak hilang|V-ing terbentuk tepat"),
T("writing","Deskripsikan gambar rekaan suasana taman dalam lima kalimat Present Continuous.","A child is running. Two people are walking. A woman is reading. A dog is sleeping. A man is drinking water.","Lima kegiatan|Agreement be|Subjek dan tindakan jelas")],"timeline",("A103",)),
U("A105","Ada apa dan di mana","Mendeskripsikan tempat dengan there is/are dan preposisi.",
"There is are|There isn't aren't|Is there are there|Some any|Posisi benda|Petunjuk lokasi",
"There is memperkenalkan keberadaan satu benda atau bahan tak terhitung; there are memperkenalkan beberapa benda. Bandingkan There is a book on the desk dengan The book is on the desk: yang pertama mengenalkan buku, yang kedua membicarakan buku yang sudah diketahui.||Pertanyaan memakai Is there atau Are there. Some lazim dalam pernyataan positif, any lazim dalam pertanyaan dan negatif. Dalam tawaran atau permintaan yang mengharapkan persetujuan, some juga dapat muncul; pola awal ini bukan aturan tanpa pengecualian.",
[("There is + singular/uncountable","There is some water.","Mengenalkan keberadaan."),("There are + plural","There are two chairs.","Benda jamak."),("Are there any + plural?","Are there any books?","Menanyakan keberadaan.")],
("There is three books.","There are three books.","Three books jamak, sehingga memakai are."),
"Our study room is small. There is a desk beside the window. There are two chairs and some books. There isn't a computer. There is some water on the desk.",
"beside=di sebelah|window=jendela|study room=ruang belajar|computer=komputer|some=beberapa/sejumlah|any=sejumlah dalam konteks tanya/negatif",
[Q("___ two chairs in the room.","There are","There is||It is","Two chairs adalah jamak."),
Q("___ any milk in the fridge?","Is there","Are there||Does there","Milk biasanya tak terhitung."),
Q("There aren't ___ books here.","any","a||an","Negatif jamak lazim memakai any."),
Q("Kalimat yang pertama kali mengenalkan tas …","There is a bag on the chair.","The bag on the chair.||Is a bag there the chair.","There is mengenalkan keberadaan."),
Q("Apa yang tidak tersedia di ruang belajar?","a computer","books||water","Bacaan menyatakan there isn't a computer.","reading"),
S("Lengkapi: There ___ some rice in the bowl.","is","Rice diperlakukan tak terhitung.")],
[T("speaking","Jelaskan ruangan rekaan. Pendamping menanyakan dua benda dengan Is there/Are there.","There is a desk. There are two chairs. Is there a lamp? Yes, there is. Are there any books? No, there aren't.","Jumlah konsisten|Pertanyaan sesuai benda|Jawaban pendek tepat"),
T("writing","Tulis iklan sudut belajar dengan empat fasilitas dan satu hal yang tidak ada.","There is a large desk. There are two chairs. There is a lamp. There are some books. There isn't a computer.","Positif dan negatif|Is/are tepat|Fasilitas jelas")],"place",("A104",)),
U("A106","Jumlah dan permintaan sederhana","Memilih much/many serta membuat permintaan makanan dan benda.",
"Countable uncountable|Much many|A lot of|A few a little|How much many|I'd like",
"Many mendampingi benda yang bisa dihitung dalam bentuk jamak; much mendampingi bahan atau konsep yang biasa tidak dihitung: many apples, much water. A lot of dapat dipakai pada keduanya. A few berarti sejumlah kecil benda terhitung; a little sejumlah kecil bahan.||How many apples? menanyakan jumlah buah. How much water? menanyakan jumlah air, sedangkan How much is it? menanyakan harga. I'd like adalah potongan bahasa yang berguna untuk permintaan: I'd like a glass of water, please. Unit satuan membuat bahan dapat dihitung: two bottles of water.",
[("How many + plural?","How many apples do we need?","Jumlah benda."),("How much + uncountable?","How much rice is there?","Jumlah bahan."),("I'd like + noun","I'd like two sandwiches.","Permintaan.")],
("How many water do you need?","How much water do you need?","Water biasa tak terhitung; gunakan much atau satuan botol."),
"For our picnic, we need six sandwiches and a little rice. We have a few apples, but we don't have much water. Ana would like two bottles of water. Each bottle costs ten thousand rupiah.",
"sandwich=roti isi|bottle=botol|need=membutuhkan|cost=berharga|a few=beberapa|a little=sedikit bahan",
[Q("How ___ apples do we need?","many","much||a little","Apples terhitung jamak."),
Q("We don't have ___ water.","much","many||a few","Water tak terhitung."),
Q("Pilih permintaan yang tepat.","I'd like a sandwich, please.","I like a sandwich now please are.||I am like a sandwich.","I'd like digunakan untuk meminta."),
Q("A little rice berarti …","sedikit nasi","beberapa butir apel||banyak kursi","A little dipakai dengan bahan tak terhitung.","meaning"),
Q("Berapa botol air yang diinginkan Ana?","two","six||ten","Bacaan menyebut two bottles.","reading"),
S("Lengkapi: two bottles ___ water.","of","Satuan wadah dihubungkan dengan of.")],
[T("speaking","Lakukan transaksi sederhana: pesan dua barang, tanyakan harga, lalu ucapkan terima kasih.","I'd like two sandwiches and a bottle of water, please. How much is that? Thank you.","Jumlah jelas|I'd like tepat|Pertanyaan harga"),
T("writing","Buat daftar belanja dengan dua benda terhitung dan dua bahan tak terhitung dalam satuan.","three apples; two oranges; a bottle of water; a bag of rice","Empat barang|Satuan bahan|Plural setelah angka")],"nouns",("A105",)),
U("A107","Bisa, boleh, dan tolong","Membedakan fungsi can serta membuat undangan sederhana.",
"Ability|Permission|Requests|Can versus be|Would like|Accept decline",
"Can dapat menyatakan kemampuan, izin, atau permintaan. Fungsi ditentukan konteks: I can swim adalah kemampuan; Can I sit here? meminta izin; Can you open the window? meminta bantuan. Bentuk kata kerjanya tetap sama, yaitu V1.||Jawaban yang kooperatif menanggapi kebutuhan lawan bicara. Untuk permintaan bantuan, Yes, I can saja dapat terasa belum menanggapi tindakan; Sure, I'll help lebih sesuai. Undangan Would you like to join us? dapat diterima atau ditolak dengan sopan. Bahasa yang tepat tidak cukup dinilai dari rumus.",
[("Can I + V1?","Can I borrow your pen?","Meminta izin."),("Can you + V1?","Can you close the door?","Meminta bantuan."),("Would you like to + V1?","Would you like to join us?","Mengundang.")],
("Can you to help me?","Can you help me?","Can langsung diikuti bentuk dasar tanpa to."),
"Ana: Can I borrow your ruler? Bima: Sure. Here you are. Ana: Thanks. Would you like to draw with us? Bima: I'd love to, but I need to leave now. Maybe tomorrow.",
"borrow=meminjam|join=bergabung|leave=pergi|sure=tentu|tomorrow=besok|maybe=mungkin",
[Q("Can I sit here? digunakan untuk …","meminta izin","menyatakan kemampuan berenang||menanyakan nama","Subjek I menunjukkan izin untuk pembicara.","interaction"),
Q("Can you ___ the window?","open","to open||opens","Can diikuti V1 tanpa to."),
Q("Jawaban kooperatif untuk Can you help me? …","Sure. What do you need?","Yes, I am a help.||No, you are can.","Jawaban menindaklanjuti permintaan.","interaction"),
Q("Undangan yang tepat …","Would you like to join us?","Would you like join us?||Are you like to join us?","Would like diikuti to + V1."),
Q("Mengapa Bima tidak ikut menggambar sekarang?","He needs to leave.","He cannot draw.||He dislikes Ana.","Penolakan disertai alasan praktis.","reading"),
S("Lengkapi: Can I ___ your pen? (meminjam)","borrow","Borrow berarti menerima pinjaman, bukan meminjamkan.","vocabulary")],
[T("speaking","Buat dialog pinjam barang dan undangan; sertakan penolakan sopan.","Can I borrow your book? Sure. Would you like to read with us? Thanks, but I need to go home.","Izin dan undangan dibedakan|V1 setelah can|Penolakan beralasan"),
T("writing","Tulis undangan tiga kalimat beserta balasan dua kalimat.","Would you like to join our reading club? We meet on Friday. Please bring a book. Thank you for inviting me. I'd love to come.","Informasi kegiatan|Waktu jelas|Balasan relevan")],"modals",("A106",)),
U("A108","Dari kalimat ke pesan utuh","Menghubungkan kalimat dan menulis pesan pendek yang dapat ditindaklanjuti.",
"And but because|Urutan informasi|Rujukan he she it|Pesan praktis|Membaca detail|Review A1",
"And menambahkan informasi, but menunjukkan kontras, because memberi alasan. Pilih penghubung sesuai hubungan makna: I like the library because it is quiet. It harus memiliki rujukan jelas, bukan muncul tanpa benda yang dapat dikenali.||Pesan praktis menjawab siapa, kegiatan apa, kapan, di mana, dan tindakan yang diminta. Susun tujuan lebih dulu, detail berikutnya, lalu penutup. Saat membaca, jangan hanya mencari satu kata yang mirip soal; cek keseluruhan informasi. Gunakan Simple Present untuk jadwal dan Present Continuous untuk kegiatan sementara yang relevan.",
[("klausa + because + alasan","I study here because it is quiet.","Hubungan sebab."),("klausa + but + kontras","I like tea, but I don't drink coffee.","Dua fakta berlawanan.")],
("I am late because but the bus is slow.","I am late because the bus is slow.","Pilih penghubung yang menjelaskan hubungan makna."),
"Hi Rafi, our reading club meets at the library on Friday at four. We usually read stories, but this week we are making posters. Please bring coloured pencils. I can bring paper. See you there! Ana",
"poster=poster|bring=membawa ke sini|paper=kertas|because=karena|but=tetapi|meet=bertemu",
[Q("I like this room ___ it is quiet.","because","but||or","Klausa kedua memberi alasan."),
Q("I like apples, ___ I don't like oranges.","but","because||so that every","Hubungannya kontras."),
Q("Pada pesan, kegiatan minggu ini adalah …","making posters","reading only||playing tennis","But menandai perubahan dari kebiasaan.","reading"),
Q("Apa yang Rafi diminta bawa?","coloured pencils","paper||rice","Ana membawa kertas; Rafi membawa pensil warna.","reading"),
Q("Pesan yang paling dapat ditindaklanjuti …","Meet me at the library on Friday at four.","Meet me sometime somewhere.||Me library meeting.","Tempat dan waktu disebut secara jelas.","writing"),
S("Lengkapi: Ana has a bag. ___ is blue.","It","It merujuk benda tunggal bag.")],
[T("speaking","Jelaskan rencana klub dalam 45–60 detik: kegiatan, tempat, waktu, perubahan minggu ini, dan permintaan.","We meet at the library on Friday at four. We usually read, but this week we are making posters. Please bring coloured pencils. I can bring paper. Can you join us?","Lima informasi tercakup|Habit/now tepat|Permintaan mudah dipahami"),
T("writing","Tulis pesan 50–70 kata tentang kegiatan rekaan. Pakai and, but, because.","Hi Lina, our drawing club meets at my house on Saturday at three. We usually draw animals, but this week we are drawing a park. Please bring pencils and a ruler. I can bring paper because I have a large pack. Can you join us? Please tell me on Friday. Thanks, Rafi.","50–70 kata|Tujuan dan tindakan jelas|Tiga penghubung bermakna")],"paragraph",("A107",))
]
